inline_styles:
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Source Sans 3',system-ui,sans-serif;color:#111;line-height:1.7;background:#fff}
a{text-decoration:none;color:#0A4A2E}
.container{max-width:1100px;margin:0 auto;padding:0 24px}
.navbar{background:#fff;border-bottom:1px solid #e5ede8;padding:12px 0;position:sticky;top:0;z-index:100;box-shadow:0 1px 4px rgba(0,0,0,.06)}
.navbar .inner{display:flex;justify-content:space-between;align-items:center}
.nav-logo{font-family:'Lexend',sans-serif;font-weight:800;color:#0A4A2E;font-size:18px}
.btn-wa-sm{background:#25D366;color:#fff;padding:8px 18px;border-radius:8px;font-weight:700;font-size:14px}
.article-wrap{display:grid;grid-template-columns:1fr 300px;gap:48px;padding:48px 0 72px;align-items:start}
article{min-width:0}
.article-meta{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:28px;font-size:14px;color:#666}
.meta-tag{background:#e8f5ee;color:#0A4A2E;padding:4px 12px;border-radius:20px;font-weight:600;font-size:12px}
h1{font-family:'Lexend',sans-serif;font-size:clamp(26px,4vw,40px);font-weight:800;color:#062E1C;line-height:1.2;margin-bottom:20px}
.article-lead{font-size:18px;color:#333;line-height:1.8;border-left:4px solid #0A4A2E;padding-left:20px;margin-bottom:36px;font-weight:500}
h2{font-family:'Lexend',sans-serif;font-size:clamp(20px,3vw,26px);font-weight:800;color:#062E1C;margin:40px 0 16px}
h3{font-size:18px;font-weight:700;color:#062E1C;margin:28px 0 12px}
p{margin-bottom:16px;color:#333;font-size:16px}
ul,ol{margin:0 0 20px 20px}
li{margin-bottom:8px;font-size:16px;color:#333}
.comparison-table{width:100%;border-collapse:collapse;margin:24px 0;font-size:15px;border-radius:12px;overflow:hidden;box-shadow:0 2px 12px rgba(0,0,0,.06)}
.comparison-table th{padding:14px 16px;text-align:left;font-weight:700}
.comparison-table td{padding:13px 16px;border-bottom:1px solid #e5ede8;vertical-align:top}
.comparison-table tr:last-child td{border-bottom:none}
.th-kemnaker{background:#0A4A2E;color:#fff}
.th-bnsp{background:#1e40af;color:#fff}
.th-aspek{background:#f8faf9;color:#062E1C}
.row-even td{background:#fafafa}
.verdict-box{background:#f0f7f4;border:2px solid #0A4A2E;border-radius:14px;padding:24px;margin:32px 0}
.verdict-box h3{margin-top:0;color:#0A4A2E}
.verdict-box ul{margin-left:16px}
.warning-box{background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:20px;margin:24px 0}
.warning-box p{margin:0;font-size:15px;color:#78350f}
.info-box{background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:20px;margin:24px 0}
.info-box p{margin:0;font-size:15px;color:#1e40af}
.cta-inline{background:#0A4A2E;border-radius:14px;padding:28px;color:#fff;text-align:center;margin:36px 0}
.cta-inline h3{font-family:'Lexend',sans-serif;font-size:20px;font-weight:800;margin:0 0 8px}
.cta-inline p{opacity:.85;margin:0 0 20px;font-size:15px}
.cta-inline a{background:#25D366;color:#fff;padding:12px 28px;border-radius:10px;font-weight:700;font-size:15px;display:inline-block}
.faq-item{border-bottom:1px solid #e5ede8;padding:16px 0}
.faq-q{width:100%;text-align:left;background:none;border:none;font-size:16px;font-weight:600;color:#062E1C;cursor:pointer;display:flex;justify-content:space-between;align-items:center;padding:0;font-family:inherit}
.faq-a{max-height:0;overflow:hidden;font-size:15px;color:#444;line-height:1.7;transition:max-height .3s ease}
.faq-a p{margin:10px 0 0}
.faq-item.open .faq-a{max-height:400px}
.faq-item.open .faq-icon{transform:rotate(45deg)}
.faq-icon{transition:transform .3s;font-size:20px}
.sidebar-card{background:#fff;border:1px solid #e5ede8;border-radius:14px;padding:20px;margin-bottom:20px;position:sticky;top:80px}
.sidebar-card h4{font-family:'Lexend',sans-serif;font-size:16px;font-weight:800;color:#062E1C;margin:0 0 14px}
.toc-list{list-style:none;margin:0;padding:0}
.toc-list li{padding:6px 0;border-bottom:1px solid #f0f0f0;font-size:14px}
.toc-list li:last-child{border:none}
.toc-list a{color:#444;font-weight:500}
.toc-list a:hover{color:#0A4A2E}
.related-card{background:#f0f7f4;border-radius:12px;padding:14px;margin-bottom:10px;display:flex;gap:10px;align-items:center}
.related-card span{font-size:22px;flex-shrink:0}
.related-card a{font-size:14px;font-weight:600;color:#062E1C;line-height:1.3}
.breadcrumb{list-style:none;display:flex;gap:6px;padding:16px 0;font-size:13px;color:#888}
.breadcrumb a{color:#0A4A2E}
@media(max-width:900px){.article-wrap{grid-template-columns:1fr}.sidebar-card{position:static}}
